WITH kept_keys AS (SELECT channel, customer_id FROM orders INTERSECT SELECT channel, customer_id FROM orders WHERE channel != 'web'), kept_rows AS (SELECT s.* FROM orders s INNER JOIN kept_keys k ON s.channel = k.channel AND s.customer_id = k.customer_id) SELECT s.id, s.customer_id, s.store_id, s.order_date, s.channel, s.discount, (SELECT SUM(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS sum_account_balance FROM kept_rows s ORDER BY discount NULLS LAST, order_date
